'use strict'
// 给人看的那一份：分 → 元的字符串。
const { yuan } = require('../src/format.ts')
const got = yuan(1234)
if (got !== '12.34') {
  console.error('yuan(1234) 实得 ' + JSON.stringify(got) + '，要的是 "12.34"')
  process.exit(1)
}

'use strict'
