// 金额的呈现：**唯一出口**（AGENTS.md 的纪律二）。
// 内部一律是分，这里换算成元，保留两位小数。
export function yuan(cents: number): string {
  const sign = cents < 0 ? '-' : ''
  const abs = Math.abs(cents)
  const whole = Math.floor(abs / 100)
  const frac = abs % 100
  return `${sign}${whole}.${String(frac).padStart(2, '0')}`
}

export function fen(yuanText: string): number {
  return Math.round(Number(yuanText) * 100)
}

